Hmm, raw-text training gave worse results (0.59 vs 0.63 preprocessed). Let me check what the predict path actually looks like, and consider a hybrid: light preprocessing baked into training that still benefits raw input.
[tool_use bash] cd /app && python3 << 'EOF'
import fasttext, pandas as pd, re
m = fasttext.load_model('/app/model.bin')  # current = trained-raw model
df = pd.read_parquet('data/test-00000-of-00001.parquet')
def clean(t):
    t = t.lower().replace('\n',' ').replace('\\n',' ').replace('\t',' ')
    t = re.sub(r"([.!?,'/()])", r" \1 ", t)
    t = re.sub(r"\s+", " ", t).strip()
    return t
def light(t):
    return t.replace('\n',' ').replace('\r',' ').replace('\t',' ')
def lower(t):
    return t.lower().replace('\n',' ').replace('\r',' ').replace('\t',' ')
modes = {'raw': light, 'lower': lower, 'preprocessed': clean}
for name, fn in modes.items():
    correct = 0
    for lbl, txt in zip(df['label'], df['text']):
        pred = m.predict(fn(txt))[0][0]
        if int(pred.replace('__label__','')) == lbl: correct += 1
    print(f"{name}: {correct/len(df):.4f}")
EOF

